package dev.zomboidmelee.boxing;
import net.minecraft.client.Minecraft;
public class LateQueueChecks37{
 static int n;static void ok(boolean b,String m){if(!b)throw new AssertionError(m);n++;}
 public static class Stage{public String getStage(){return "AFTER_SKY";}}
 static Laser32.Beam beam(Object e,boolean first){double[]id=Matrix32.identity(),zero={0,0,0};return new Laser32.Beam(e,new Object(),id,id,zero,zero,.004,0xff0000,false,first,null,null);}
 public static void main(String[]args){var mc=Minecraft.INSTANCE;mc.player=new LaserChecks32.Local();mc.level=new Object();mc.screen=null;LaserLate37.QUEUE.clear();for(int i=0;i<100;i++)LaserLate37.enqueue(beam(new Object(),false));ok(LaserLate37.QUEUE.size()==32,"bounded per-frame queue");LaserLate37.enqueue(beam(mc.player,true));ok(LaserLate37.QUEUE.size()==32&&LaserLate37.QUEUE.get(mc.player).first(),"local first-person beam retains priority");LaserLate37.enqueue(beam(mc.player,false));ok(LaserLate37.QUEUE.get(mc.player).first(),"third-person duplicate cannot replace first-person muzzle");LaserLate37.stage(new Stage());ok(LaserLate37.QUEUE.isEmpty()&&!LaserLate37.ready,"new frame discards stale transforms");double[][]s=LaserLate37.segment(new double[]{0,0,1},new double[]{0,0,-10},new double[3],Matrix32.identity());ok(s!=null&&Math.abs(s[0][2]+.08)<1e-6,"clip a crossing beam at the camera near plane");ok(LaserLate37.segment(new double[]{0,0,1},new double[]{0,0,2},new double[3],Matrix32.identity())==null,"fully behind-camera beam hidden");for(int i=1;i<100;i++){s=LaserLate37.segment(new double[]{.1,.2,-.3},new double[]{.2,-.1,-i},new double[3],Matrix32.identity());ok(s!=null&&Double.isFinite(s[1][2]),"finite distant segments");}LaserLate37.enqueue(beam(mc.player,true));LaserLate37.ready=false;LaserLate37.finish();ok(LaserLate37.QUEUE.isEmpty(),"missing depth cannot replay old beams");System.out.println("LATE_LASER_QUEUE_BUDGET_LOCAL_PRIORITY_SCOPE_NEAR_PLANE_FRAME_LIFECYCLE_CHECKS="+n);}
}
